  "$defs": {
    "Id": {
      "type": "string",
      "pattern": "^[a-z][a-z0-9_]*_[0-9a-f]{32}$"
    },
    "Revision": {
      "type": "integer",
      "minimum": 1,
      "maximum": 9007199254740991
    },
    "Count": {
      "type": "integer",
      "minimum": 0,
      "maximum": 9007199254740991
    },
    "Digest": {
      "type": "string",
      "pattern": "^sha256:[0-9a-f]{64}$"
    },
    "Time": {
      "type": "string",
      "format": "date-time",
      "pattern": "Z$"
    },
    "Decimal": {
      "type": "string",
      "pattern": "^(0|[1-9][0-9]*)(\\.[0-9]{1,9})?$"
    },
    "Amount": {
      "type": "object",
      "properties": {
        "unit": {
          "type": "string",
          "minLength": 1,
          "maxLength": 32,
          "description": "准确计量单位；不同单位不可直接相加"
        },
        "value": {
          "$ref": "#/$defs/Decimal",
          "description": "该单位的非负十进制数量"
        }
      },
      "required": [
        "unit",
        "value"
      ],
      "additionalProperties": false
    },
    "ObjectRef": {
      "type": "object",
      "properties": {
        "owner_id": {
          "$ref": "#/$defs/Id",
          "description": "该事实的逻辑负责方，不是当前 worker"
        },
        "object_id": {
          "$ref": "#/$defs/Id",
          "description": "所属类型的原对象身份"
        },
        "revision": {
          "$ref": "#/$defs/Revision",
          "description": "当前对象可见修订，从1开始；不与其他修订混用"
        },
        "tenant_id": {
          "$ref": "#/$defs/Id",
          "description": "受信租户；引用须与认证数据域一致"
        }
      },
      "required": [
        "owner_id",
        "object_id",
        "revision",
        "tenant_id"
      ],
      "additionalProperties": false
    },
    "ComponentRef": {
      "type": "object",
      "properties": {
        "component_id": {
          "$ref": "#/$defs/Id",
          "description": "不可变版本化组件的稳定身份"
        },
        "version": {
          "type": "string",
          "minLength": 1,
          "maxLength": 128,
          "description": "准确版本；禁止解析为 latest"
        },
        "digest": {
          "$ref": "#/$defs/Digest",
          "description": "准确对象或配置摘要，不提供授权"
        }
      },
      "required": [
        "component_id",
        "version",
        "digest"
      ],
      "additionalProperties": false
    },
    "ContentRef": {
      "type": "object",
      "properties": {
        "tenant_id": {
          "$ref": "#/$defs/Id",
          "description": "受信租户范围；载荷必须与认证上下文一致"
        },
        "owner_id": {
          "$ref": "#/$defs/Id",
          "description": "该事实的逻辑负责方，不是当前 worker"
        },
        "content_id": {
          "$ref": "#/$defs/Id",
          "description": "原内容身份"
        },
        "version": {
          "$ref": "#/$defs/Revision",
          "description": "准确版本；禁止解析为 latest"
        },
        "hash": {
          "$ref": "#/$defs/Digest",
          "description": "准确字节的 SHA256 摘要"
        },
        "media_type": {
          "type": "string",
          "pattern": "^[A-Za-z0-9.+-]+/[A-Za-z0-9.+-]+$",
          "description": "准确字节的媒体类型"
        },
        "byte_length": {
          "$ref": "#/$defs/Count",
          "description": "准确字节长度；不按字符数代替"
        }
      },
      "required": [
        "tenant_id",
        "owner_id",
        "content_id",
        "version",
        "hash",
        "media_type",
        "byte_length"
      ],
      "additionalProperties": false
    },
    "CollectionSummary": {
      "type": "object",
      "properties": {
        "collection_revision": {
          "$ref": "#/$defs/Revision",
          "description": "关系集合修订，变更与原 owner 事务共同提交"
        },
        "total_count": {
          "$ref": "#/$defs/Count",
          "description": "原查询范围的全部关系数量"
        },
        "unresolved_count": {
          "$ref": "#/$defs/Count",
          "description": "其中仍未核清的关系数量"
        },
        "items_cursor": {
          "type": "string",
          "minLength": 1,
          "maxLength": 2048,
          "description": "当前集合的有界分页入口；省略不自动证明完整"
        },
        "complete": {
          "type": "boolean",
          "description": "原 owner 关系索引完整性，不是业务完成"
        }
      },
      "required": [
        "collection_revision",
        "total_count",
        "unresolved_count",
        "complete"
      ],
      "additionalProperties": false
    },
    "BudgetBalance": {
      "type": "object",
      "properties": {
        "unit": {
          "type": "string",
          "minLength": 1,
          "maxLength": 32,
          "description": "准确计量单位；不同单位不可直接相加"
        },
        "limit": {
          "$ref": "#/$defs/Decimal",
          "description": "未来承诺准入上限"
        },
        "reserved": {
          "$ref": "#/$defs/Decimal",
          "description": "尚未释放的费用承诺"
        },
        "spent": {
          "$ref": "#/$defs/Decimal",
          "description": "原真实累计 gross_spent，可因真实更正超出limit"
        }
      },
      "required": [
        "unit",
        "limit",
        "reserved",
        "spent"
      ],
      "additionalProperties": false
    },
    "Requirement": {
      "type": "object",
      "description": "Orchestrator 已接纳的不可变条件版本；生效集合由 GoalRevision 选择",
      "properties": {
        "requirement_id": {
          "$ref": "#/$defs/Id",
          "description": "同 Task 内稳定身份；删后不重用"
        },
        "revision": {
          "$ref": "#/$defs/Revision",
          "description": "定义版本；同版本不可改"
        },
        "kind": {
          "enum": [
            "effect",
            "quality"
          ],
          "description": "本类型声明的业务种类"
        },
        "statement_ref": {
          "$ref": "#/$defs/ContentRef",
          "description": "准确条件描述"
        },
        "source_refs": {
          "type": "array",
          "items": {
            "$ref": "#/$defs/SourceEvidence"
          },
          "minItems": 1,
          "maxItems": 100,
          "description": "准确原始输入、附件或衍生依据集合；不把引用升级成权限"
        },
        "origin": {
          "enum": [
            "explicit_user",
            "derived"
          ],
          "description": "条件来自显式用户要求或必要推导；不等于授权等级"
        },
        "rule_ref": {
          "$ref": "#/$defs/ComponentRef",
          "description": "定义通过谓词的准确规则，不是执行实现"
        },
        "rule_parameters_ref": {
          "$ref": "#/$defs/ContentRef",
          "description": "符合原rule闭合Schema的准确目标、范围和阈值参数"
        },
        "required": {
          "type": "boolean",
          "description": "是否为必要条件；显式硬要求不能由模型降低"
        },
        "adoption_id": {
          "$ref": "#/$defs/Id",
          "description": "原 Task owner 的采纳决定"
        }
      },
      "required": [
        "requirement_id",
        "revision",
        "kind",
        "statement_ref",
        "source_refs",
        "origin",
        "rule_ref",
        "required",
        "adoption_id"
      ],
      "additionalProperties": false
    },
    "WaitReason": {
      "type": "object",
      "properties": {
        "kind": {
          "enum": [
            "input",
            "authorization",
            "dependency",
