          "$ref": "#/$defs/Revision",
          "description": "当前对象可见修订，从1开始；不与其他修订混用"
        },
        "session_ref": {
          "$ref": "#/$defs/ObjectRef",
          "description": "原应用会话及准确修订；不表示执行归属"
        },
        "branch_id": {
          "$ref": "#/$defs/Id",
          "description": "本条消息或输入所属原分支；迟到结果不迁移分支"
        },
        "message_id": {
          "$ref": "#/$defs/Id",
          "description": "不可变原消息身份；编辑保存新准确正文及明确版本"
        },
        "seq": {
          "$ref": "#/$defs/Revision",
          "description": "同Session内已提交消息序号；唯一且单调，不按墙钟排序"
        },
        "kind": {
          "enum": [
            "submit_goal",
            "steer",
            "input",
            "enqueue_goal_after"
          ],
          "description": "本类型声明的业务种类"
        },
        "content_ref": {
          "$ref": "#/$defs/ContentRef",
          "description": "原正文的准确版本；当前读取仍检查用途与权限"
        },
        "history_cutoff": {
          "$ref": "#/$defs/Count",
          "description": "首次固定的会话已提交seq上界，不随模型运行读取最新历史"
        },
        "target_task_ref": {
          "$ref": "#/$defs/ObjectRef",
          "description": "本次steer或Task型回答的准确原Task；不是新目标路由"
        },
        "predecessor_task_ref": {
          "$ref": "#/$defs/ObjectRef",
          "description": "后续目标等待其工作封闭的原Task；仅终态不证明封闭"
        },
        "expected_goal_revision": {
          "$ref": "#/$defs/Revision",
          "description": "原输入要作用的目标版本；冲突时不得自动改成当前值"
        },
        "request_ref": {
          "$ref": "#/$defs/ObjectRef",
          "description": "实际业务owner保存的准确InputRequest与请求版本"
        },
        "dispatch_command_ref": {
          "$ref": "#/$defs/ObjectRef",
          "description": "首次发送前固定；不是网络发送尝试"
        },
        "state": {
          "enum": [
            "queued",
            "sending",
            "applied",
            "rejected",
            "withdrawn"
          ],
          "description": "该记录自己的生命周期；具体取值见类型列"
        },
        "withdrawal_requested": {
          "type": "boolean",
          "description": "用户请求撤回；sending后为true不等于业务已撤回"
        },
        "task_ref": {
          "$ref": "#/$defs/ObjectRef",
          "description": "Task型输入的原接纳结果映射；独立应用请求可以没有Task"
        },
        "created_at": {
          "$ref": "#/$defs/Time",
          "description": "创建原记录的可信时点"
        }
      },
      "required": [
        "submission_id",
        "tenant_id",
        "owner_id",
        "revision",
        "session_ref",
        "branch_id",
        "message_id",
        "seq",
        "kind",
        "content_ref",
        "history_cutoff",
        "state",
        "withdrawal_requested",
        "created_at"
      ],
      "additionalProperties": false,
      "allOf": [
        {
          "if": {
            "properties": {
              "kind": {
                "const": "steer"
              }
            }
          },
          "then": {
            "required": [
              "target_task_ref",
              "expected_goal_revision"
            ]
          }
        },
        {
          "if": {
            "properties": {
              "kind": {
                "const": "input"
              }
            }
          },
          "then": {
            "required": [
              "request_ref"
            ]
          }
        },
        {
          "if": {
            "properties": {
              "kind": {
                "const": "enqueue_goal_after"
              }
            }
          },
          "then": {
            "required": [
              "predecessor_task_ref"
            ]
          }
        },
        {
          "if": {
            "properties": {
              "state": {
                "enum": [
                  "sending",
                  "applied"
                ]
              }
            }
          },
          "then": {
            "required": [
              "dispatch_command_ref"
            ]
          }
        },
        {
          "if": {
            "properties": {
              "state": {
                "const": "applied"
              },
              "kind": {
                "enum": [
                  "submit_goal",
                  "steer",
                  "enqueue_goal_after"
                ]
              }
            }
          },
          "then": {
            "required": [
              "task_ref"
            ]
          }
        },
        {
          "if": {
            "properties": {
              "kind": {
                "const": "input"
              }
            },
            "required": [
              "target_task_ref"
            ]
          },
          "then": {
            "required": [
              "expected_goal_revision"
            ]
          }
        }
      ]
    },
    "InputRequest": {
      "type": "object",
      "description": "原业务 owner 保存；明确语义不替代高影响动作 Confirmation",
      "properties": {
        "request_id": {
          "$ref": "#/$defs/Id",
          "description": "原请求/确认身份"
        },
        "tenant_id": {
          "$ref": "#/$defs/Id",
          "description": "受信租户范围；载荷必须与认证上下文一致"
        },
        "owner_id": {
          "$ref": "#/$defs/Id",
          "description": "该事实的逻辑负责方，不是当前 worker"
        },
        "revision": {
          "$ref": "#/$defs/Revision",
          "description": "当前对象可见修订，从1开始；不与其他修订混用"
        },
        "target_ref": {
          "$ref": "#/$defs/ObjectRef",
          "description": "此请求实际消费的业务对象；可为Task或独立应用对象"
        },
        "goal_revision": {
          "$ref": "#/$defs/Revision",
          "description": "完整目标及有效条件集合版本"
        },
        "purpose": {
          "enum": [
            "clarify_goal",
            "supply_context",
            "accept_quality",
            "business_input"
          ],
          "description": "请求的业务用途；澄清目标不等于批准高影响动作"
        },
        "question_ref": {
          "$ref": "#/$defs/ContentRef",
          "description": "原owner固定的准确问题正文及来源上下文"
        },
        "answer_schema_ref": {
          "$ref": "#/$defs/ComponentRef",
          "description": "原 owner 登记的闭合 Schema"
        },
        "preview_refs": {
          "type": "array",
          "items": {
            "$ref": "#/$defs/ContentRef"
          },
          "minItems": 0,
          "maxItems": 100,
          "description": "原界面需呈现的准确正文；不是阅读证明"
        },
        "expires_at": {
          "$ref": "#/$defs/Time",
          "description": "原资格或首次接纳截止；查询不延长"
        },
        "state": {
          "enum": [
            "pending",
            "answered",
            "expired",
            "withdrawn"
          ],
          "description": "该记录自己的生命周期；具体取值见类型列"
        },
        "answer_ref": {
          "$ref": "#/$defs/ContentRef",
          "description": "已一次消费的准确回答"
        },
        "consumed_by": {
          "$ref": "#/$defs/Id",
          "description": "一次消费原命令"
        },
        "answered_at": {
          "$ref": "#/$defs/Time",
          "description": "回答消费时间"
        },
        "candidate_ref": {
          "$ref": "#/$defs/ContentRef",
          "description": "accept_quality 所验收的准确成果版本与摘要"
        },
        "limitations_ref": {
          "$ref": "#/$defs/ContentRef",
          "description": "accept_quality 必须呈现的准确限制正文"
        }
      },
      "required": [
        "request_id",
        "tenant_id",
        "owner_id",
        "revision",
        "target_ref",
        "purpose",
        "question_ref",
        "answer_schema_ref",
        "preview_refs",
        "expires_at",
        "state"
      ],
      "additionalProperties": false,
      "allOf": [
        {
          "if": {
            "properties": {
              "state": {
                "const": "answered"
              }
            }
          },
          "then": {
            "required": [
              "answer_ref",
              "consumed_by",
              "answered_at"
            ]
          }
        },
        {
          "if": {
            "properties": {
              "purpose": {
                "const": "accept_quality"
              }
            }
          },
          "then": {
            "required": [
              "candidate_ref",
              "limitations_ref",
              "goal_revision"
            ]
          }
        }
      ]
    },
    "RuleDefinition": {
      "type": "object",
      "description": "原规则owner登记的不可变业务配置；模型不能自行扩大allowed_basis",
      "properties": {
        "rule_ref": {
          "$ref": "#/$defs/ComponentRef",
          "description": "规则注册表的准确版本"
        },
        "kind": {
          "enum": [
            "effect",
            "quality"
          ],
          "description": "效果条件或质量条件"
        },
        "parameters_schema_ref": {
          "$ref": "#/$defs/ComponentRef",
          "description": "参数的闭合Schema"
        },
        "predicate": {
          "enum": [
            "historical_effect",
            "current_state",
            "quality"
          ],
          "description": "原历史效果、当前状态或质量谓词"
        },
        "allowed_basis": {
          "type": "array",
          "items": {
            "enum": [
              "verified",
              "assessed",
              "user_accepted"
            ]
          },
          "minItems": 1,
          "maxItems": 3,
          "uniqueItems": true,
          "description": "该规则允许采用的判断依据"
        },
        "allow_user_acceptance": {
          "type": "boolean",
          "description": "是否允许本人验收替代该质量判断"
        },
        "required_evidence_schema_ref": {
          "$ref": "#/$defs/ComponentRef",
          "description": "证据类型及最低要求"
        },
        "scope_schema_ref": {
          "$ref": "#/$defs/ComponentRef",
          "description": "资源、覆盖和限制的闭合范围"
        },
        "max_observation_age_seconds": {
          "$ref": "#/$defs/Count",
          "description": "current_state必须给有限观察年龄"
        },
        "risk_class": {
          "enum": [
            "ordinary",
            "high_impact"
          ],
          "description": "高影响自动判断要求独立校准和零陈旧门禁"
        },
        "applicability_policy_ref": {
          "$ref": "#/$defs/ComponentRef",
          "description": "证据适用性及缺陷处理政策"
        }
      },
      "required": [
        "rule_ref",
        "kind",
        "parameters_schema_ref",
        "predicate",
        "allowed_basis",
        "allow_user_acceptance",
        "required_evidence_schema_ref",
        "scope_schema_ref",
        "risk_class",
        "applicability_policy_ref"
      ],
      "additionalProperties": false,
      "allOf": [
        {
          "if": {
            "properties": {
              "kind": {
                "const": "effect"
              }
            }
          },
          "then": {
            "properties": {
              "allowed_basis": {
                "const": [
                  "verified"
                ]
              },
              "allow_user_acceptance": {
                "const": false
              },
              "predicate": {
                "enum": [
                  "historical_effect",
                  "current_state"
                ]
              }
            }
          }
        },
        {
          "if": {
            "properties": {
              "predicate": {
                "const": "current_state"
              }
            }
          },
          "then": {
            "required": [
              "max_observation_age_seconds"
            ]
          }
        },
        {
          "if": {
            "properties": {
              "allow_user_acceptance": {
                "const": true
              }
            }
          },
          "then": {
            "properties": {
              "kind": {
                "const": "quality"
              },
              "allowed_basis": {
                "contains": {
                  "const": "user_accepted"
                }
              }
            }
          }
        },
        {
          "if": {
            "properties": {
              "kind": {
                "const": "quality"
              }
            }
          },
          "then": {
            "properties": {
              "predicate": {
                "const": "quality"
              }
            }
          }
        },
        {
          "if": {
            "properties": {
              "allow_user_acceptance": {
                "const": false
              }
            }
          },
          "then": {
            "properties": {
              "allowed_basis": {
                "not": {
                  "contains": {
                    "const": "user_accepted"
                  }
                }
              }
            }
          }
        }
      ]
    },
    "GoalDocument": {
      "type": "object",
      "description": "原Task owner确定性生成的完整目标包；解释语义发生在条件提炼阶段",
      "properties": {
        "format_version": {
          "const": 1,
          "description": "确定性目标包格式版本"
        },
        "initial_goal_ref": {
          "$ref": "#/$defs/ContentRef",
          "description": "完整初始原文；若已是目标包，owner须读取并保留其最初引用，不无限嵌套"
        },
        "amendment_refs": {
          "type": "array",
          "items": {
            "$ref": "#/$defs/ContentRef"
          },
          "minItems": 0,
          "maxItems": 100,
          "description": "按受信提交顺序保存的准确本人补充；上限触发明确整理/新目标，不截断"
        }
      },
      "required": [
        "format_version",
        "initial_goal_ref",
        "amendment_refs"
      ],
      "additionalProperties": false
    },
    "ScheduleSpec": {
      "description": "首版有限调度规则，日历依外层固定时区；不接受cron/RRULE或任意脚本",
      "oneOf": [
        {
          "type": "object",
          "description": "时区/tzdb与启停区间由外层Schedule固定",
          "properties": {
            "type": {
              "const": "once_at",
              "description": "闭合规则种类"
            },
            "at": {
              "$ref": "#/$defs/Time",
              "description": "准确UTC计划时点；创建要求严格晚于effective_after"
            }
          },
          "required": [
            "type",
            "at"
          ],
          "additionalProperties": false
        },
        {
          "type": "object",
          "description": "时区/tzdb与启停区间由外层Schedule固定",
          "properties": {
            "type": {
              "const": "interval",
              "description": "闭合规则种类"
            },
            "anchor_at": {
              "$ref": "#/$defs/Time",
              "description": "UTC锚点，重启不改变"
            },
            "every_seconds": {
              "type": "integer",
              "minimum": 1,
              "maximum": 9007199254740991,
              "description": "固定正整数间隔"
            }
          },
          "required": [
            "type",
            "anchor_at",
            "every_seconds"
          ],
          "additionalProperties": false
        },
        {
          "type": "object",
          "description": "时区/tzdb与启停区间由外层Schedule固定",
          "properties": {
            "type": {
              "const": "daily",
              "description": "闭合规则种类"
            },
            "local_time": {
              "type": "string",
              "pattern": "^(?:[01][0-9]|2[0-3]):[0-5][0-9]:[0-5][0-9]$",
              "description": "当地HH:MM:SS，秒精度；无时区或闰秒字段"
            }
          },
          "required": [
            "type",
            "local_time"
          ],
          "additionalProperties": false
        },
        {
          "type": "object",
          "description": "时区/tzdb与启停区间由外层Schedule固定",
          "properties": {
            "type": {
              "const": "weekly",
              "description": "闭合规则种类"
            },
            "local_time": {
              "type": "string",
              "pattern": "^(?:[01][0-9]|2[0-3]):[0-5][0-9]:[0-5][0-9]$",
              "description": "当地HH:MM:SS，秒精度；无时区或闰秒字段"
            },
            "weekdays": {
              "type": "array",
              "items": {
                "type": "integer",
                "minimum": 1,
                "maximum": 7
              },
              "minItems": 1,
              "maxItems": 7,
              "uniqueItems": true,
              "description": "ISO星期；必须去重升序"
            }
          },
          "required": [
            "type",
            "local_time",
            "weekdays"
          ],
          "additionalProperties": false
        },
        {
          "type": "object",
          "description": "时区/tzdb与启停区间由外层Schedule固定",
          "properties": {
            "type": {
              "const": "monthly",
              "description": "闭合规则种类"
            },
            "local_time": {
              "type": "string",
              "pattern": "^(?:[01][0-9]|2[0-3]):[0-5][0-9]:[0-5][0-9]$",
              "description": "当地HH:MM:SS，秒精度；无时区或闰秒字段"
            },
            "monthdays": {
              "type": "array",
              "items": {
                "type": "integer",
                "minimum": 1,
                "maximum": 31
              },
              "minItems": 1,
              "maxItems": 31,
              "uniqueItems": true,
              "description": "当地月日；必须去重升序，不存在的日期跳过"
            }
          },
          "required": [
            "type",
            "local_time",
            "monthdays"
          ],
          "additionalProperties": false
        }
      ]
    }
  }
}
